    if (/^(https?:|data:|mailto:|#)/i.test(p)) continue;
    const base = decodeURIComponent(p.split("/").pop() || "");
    if (ATTACHMENT_EXTS.has(base.split(".").pop().toLowerCase())) push(m[0], base);
