  const appJson = await readJson(adapter, APP_JSON, {});
  const filters = Array.isArray(appJson.userIgnoreFilters) ? appJson.userIgnoreFilters.slice() : [];
  const idx = filters.findIndex((f) => String(f).trim() === pattern);
